const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const point = ee.Geometry.Point(100.141422, 20.248364);
    const buffer = point.buffer(100); // 100-meter buffer around the point for robust sampling

    const date2015 = ee.Date('2015-01-27');
    const date2020 = ee.Date('2020-01-25');
    const searchWindowDays = 3; // Search window for images around the target date

    // 2. Data Acquisition & Pre-processing Function
    const getLandsatImage = (targetDate) => {
      const collection = ee.ImageCollection('LANDSAT/LC08/C01/T1_SR')
        .filterBounds(point)
        .filterDate(targetDate.advance(-searchWindowDays, 'day'), targetDate.advance(searchWindowDays + 1, 'day'))
        .sort('system:time_start')
        .aside(function(col) {
          if (col.size().getInfo() === 0) {
            console.log(`Warning: No Landsat 8 images found near ${targetDate.format('YYYY-MM-dd').getInfo()} within the search window.`);
          }
        });

      // Simple cloud mask function for Landsat 8 SR
      // Bits 3 and 5 are cloud shadow and cloud, respectively.
      const cloudMask = (image) => {
        const qa = image.select('pixel_qa');
        const cloud = qa.bitwiseAnd(1 << 5)
          .and(qa.bitwiseAnd(1 << 7))
          .or(qa.bitwiseAnd(1 << 3)); // cloud shadow
        return image.updateMask(cloud.not());
      };

      const image = collection.map(cloudMask).first();
      return image;
    };

    // Get images for both periods
    const image2015 = getLandsatImage(date2015);
    const image2020 = getLandsatImage(date2020);

    // Check for empty collections (C1)
    if (!image2015) {
      console.log(`No Landsat image found near ${date2015.format('YYYY-MM-dd').getInfo()}.`);
      console.log('C1');
      return;
    }
    if (!image2020) {
      console.log(`No Landsat image found near ${date2020.format('YYYY-MM-dd').getInfo()}.`);
      console.log('C1');
      return;
    }

    // Band 1 (Coastal Aerosol) is a good proxy for suspended sediment/turbidity.
    const bandName = 'B1'; // Landsat 8 Coastal Aerosol band

    // 3. Processing & Calculation
    const calculateSediment = async (image, dateStr) => {
      const scale = 30; // Landsat resolution
      const reducer = ee.Reducer.mean();

      // Ensure the band exists
      const bandNames = image.bandNames().getInfo();
      if (!bandNames.includes(bandName)) {
        console.log(`Error: Band '${bandName}' not found in image for ${dateStr}.`);
        console.log('D');
        return null;
      }

      const clippedImage = image.select(bandName).clip(buffer);

      // Check pixel count (C2)
      const pixelCount = await clippedImage.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: buffer,
        scale: scale,
        maxPixels: 1e9,
      }).get(bandName).getInfo();

      if (pixelCount === 0) {
        console.log(`No valid pixels remaining in ROI for ${dateStr} after masking.`);
        console.log('C2');
        return null;
      }

      // Calculate mean sediment value
      const meanSediment = await clippedImage.reduceRegion({
        reducer: reducer,
        geometry: buffer,
        scale: scale,
        maxPixels: 1e9,
      }).get(bandName).getInfo();

      if (meanSediment === null || isNaN(meanSediment)) {
        console.log(`Calculation failed for ${dateStr}. Result is None/NaN.`);
        console.log('C3');
        return null;
      }

      return { value: meanSediment, pixels: pixelCount };
    };

    console.log(`Image 2015 Path: ${image2015.get('system:id').getInfo()}`);
    console.log(`Image 2020 Path: ${image2020.get('system:id').getInfo()}`);

    const result2015 = await calculateSediment(image2015, date2015.format('YYYY-MM-dd').getInfo());
    const result2020 = await calculateSediment(image2020, date2020.format('YYYY-MM-dd').getInfo());

    // Handle C2/C3 propagating from calculateSediment
    if (result2015 === null || result2020 === null) {
      // The C2/C3 message would have been printed inside calculateSediment
      return;
    }

    // 4. Comparison & Final Answer
    console.log(`Sediment (B1) Jan 27, 2015: ${result2015.value.toFixed(2)} (Pixels: ${result2015.pixels})`);
    console.log(`Sediment (B1) Jan 25, 2020: ${result2020.value.toFixed(2)} (Pixels: ${result2020.pixels})`);

    if (result2015.value > result2020.value) {
      console.log('A'); // Yes, more sediment in 2015
    } else {
      console.log('B'); // No, not more sediment in 2015
    }

  } catch (error) {
    console.log(`An unexpected error occurred: ${error.message}`);
    console.log('D'); // General error / Code issue
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
